package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.InventoryDtos.*; import com.vynedam.stockai.model.Batch; import com.vynedam.stockai.security.CurrentUser; import com.vynedam.stockai.service.InventoryService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class InventoryController { private final InventoryService service;private final CurrentUser current;public InventoryController(InventoryService s,CurrentUser c){service=s;current=c;}@GetMapping("/batches")List<Batch> list(){return service.list();}@PostMapping("/batches")@PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','WAREHOUSE_EXECUTIVE')")ResponseEntity<Batch> create(@Valid@RequestBody BatchRequest r,Authentication a){return ResponseEntity.status(201).body(service.create(r,current.id(a)));}@PostMapping("/batches/{id}/release")@PreAuthorize("hasAnyRole('SUPER_ADMIN','QUALITY_MANAGER')")Batch release(@PathVariable String id){return service.release(id);}@PostMapping("/movements")@PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','PRODUCTION_MANAGER','WAREHOUSE_EXECUTIVE','DISPATCH_EXECUTIVE')")Batch move(@Valid@RequestBody MovementRequest r,Authentication a){return service.move(r,current.id(a));}}
